post3 :: Post
post3 =
  Post
    { postTitle = "Reverse-engineering Grok Build from one stripped binary"
    , postDate = "2026-07-10T12:37:48+07:00"
    , postDateLabel = "Jul 10, 2026"
    , postSlug = "reverse-engineering-grok-build-cli"
    , postSection = "thought"
    , postStatus = "published"
    , postTags = ["llm", "development", "reverse-engineering", "agents"]
    , postExcerpt = ""
    , postBanner = "/assets/banners/survival.jpg"
    , postOgTitle = "Reverse-engineering Grok Build: Inside a Rust Agent CLI"
    , postOgDescription = "A practical investigation of Grok Build's stripped Rust binary, ACP interface, agent loop, tool runtime, subagents, persistence model, and the safest ways to instrument it."
    , postOgImage = ""
    , postBody = [Paragraph [Text "I started this investigation with a simple assumption: if the Grok terminal client was distributed as JavaScript, then understanding it might be mostly a matter of unpacking a bundle, finding source maps, and following module imports. That would have been the easy route. The installation looked small from the outside: two commands, ", Code "grok", Text " and ", Code "agent", Text ", both placed in ", Code "~/.grok/bin/", Text ". But the first few terminal commands changed the direction of the investigation completely."], Paragraph [Text "Grok Build 0.2.93 is not a packaged Node.js application. It is a 153 MiB stripped, statically linked Rust executable containing the TUI, ACP server, session engine, tool runtime, networking, Git integration, sandboxing, and subagent coordination in one binary. There is no JavaScript module graph to unfold. There is, however, a surprising amount of architecture still visible if we stop treating decompilation as the only way to learn from a binary."], Paragraph [Text "This article follows that path: identify the artifact, recover its Rust structure from ELF metadata and embedded tracing paths, interrogate its public ACP boundary, reconstruct the agent loop, and decide where modification is actually useful. The work here was performed on my own local installation, without changing the installed executable or sending an inference request."], Heading 2 "table-of-contents" [Text "Table of Contents"], Paragraph [Link "#start-with-the-artifact-not-the-interface" Nothing [Text "1. Start with the artifact, not the interface"], HardBreak, Link "#proving-that-it-is-native-rust" Nothing [Text "2. Proving that it is native Rust"], HardBreak, Link "#what-stripped-really-removes" Nothing [Text "3. What stripped really removes"], HardBreak, Link "#recovering-the-internal-crate-map" Nothing [Text "4. Recovering the internal crate map"], HardBreak, Link "#reconstructing-the-agent-loop" Nothing [Text "5. Reconstructing the agent loop"], HardBreak, Link "#acp-is-the-cleanest-observation-point" Nothing [Text "6. ACP is the cleanest observation point"], HardBreak, Link "#how-subagents-are-represented" Nothing [Text "7. How subagents are represented"], HardBreak, Link "#persistence-makes-the-runtime-inspectable" Nothing [Text "8. Persistence makes the runtime inspectable"], HardBreak, Link "#modification-without-patching-machine-code" Nothing [Text "9. Modification without patching machine code"], HardBreak, Link "#when-native-decompilation-is-still-useful" Nothing [Text "10. When native decompilation is still useful"], HardBreak, Link "#a-practical-research-workflow" Nothing [Text "11. A practical research workflow"], HardBreak, Link "#what-this-tells-us-about-coding-agents" Nothing [Text "12. What this tells us about coding agents"]], Heading 2 "start-with-the-artifact-not-the-interface" [Text "Start with the artifact, not the interface"], Paragraph [Text "The installer creates four visible paths, but only one real executable:"], CodeBlock (Just "text") [Text "~/.local/bin/grok  -> ~/.grok/bin/grok\n~/.local/bin/agent -> ~/.grok/bin/agent\n\n~/.grok/bin/grok  -> ../downloads/grok-linux-x86_64\n~/.grok/bin/agent -> ../downloads/grok-linux-x86_64\n"], Paragraph [Text "That is worth checking before doing anything more sophisticated. Alternate command names sometimes activate different behavior through ", Code "argv[0]", Text ", as BusyBox does. In this build, invoking the target through ", Code "agent", Text " produces the same top-level CLI as ", Code "grok", Text ". The actual non-TUI agent interface is a subcommand:"], CodeBlock (Just "bash") [Text "grok agent stdio\ngrok agent serve\ngrok agent headless\n"], Paragraph [Text "The first useful inspection is deliberately boring:"], CodeBlock (Just "bash") [Text "target=", Span "hljs-string" [Text "\"", Span "hljs-variable" [Text "$HOME"], Text "/.grok/downloads/grok-linux-x86_64\""], Text "\n\nfile -L ", Span "hljs-string" [Text "\"", Span "hljs-variable" [Text "$target"], Text "\""], Text "\n", Span "hljs-built_in" [Text "sha256sum"], Text " ", Span "hljs-string" [Text "\"", Span "hljs-variable" [Text "$target"], Text "\""], Text "\nreadelf -hW ", Span "hljs-string" [Text "\"", Span "hljs-variable" [Text "$target"], Text "\""], Text "\nreadelf -SW ", Span "hljs-string" [Text "\"", Span "hljs-variable" [Text "$target"], Text "\""], Text "\nreadelf -dW ", Span "hljs-string" [Text "\"", Span "hljs-variable" [Text "$target"], Text "\""], Text "\n"], Paragraph [Image "/assets/images/makima.webp" "cult" Nothing], Paragraph [Text "The filesystem relationship can be reduced to one small map:"], CodeBlock (Just "text") [Text "invocation              installed symlink                executable\n\ngrok  ─────────►  ~/.grok/bin/grok  ───────────┐\n                                               ├──► grok-linux-x86_64\nagent ─────────►  ~/.grok/bin/agent ───────────┘    159,465,672 bytes\n\nBoth names resolve to the same inode and the same program.\nAgent-server mode is selected later by the `grok agent …` subcommand.\n"], Paragraph [Text "For version 0.2.93, the result was:"], Table [[[Text "Property"], [Text "Observed value"]]] [[[Text "Format"], [Text "ELF 64-bit, x86-64"]], [[Text "ELF type"], [Code "DYN", Text ", used here as a position-independent executable"]], [[Text "Linking"], [Text "Static PIE"]], [[Text "Symbols"], [Text "Stripped"]], [[Text "Size"], [Text "159,465,672 bytes"]], [[Text "Build ID"], [Code "b2a926bda144f1fa29d85f30e4814e47c467c4ad"]], [[Text "CLI build"], [Code "f00f96316d"]], [[Text "SHA-256"], [Code "4e0738d3b5550f3c842bc0ae69f468815c6329c008a110d0c27a694dc3401135"]]], Paragraph [Text "Static PIE explains several later constraints. Address-space layout randomization still applies, but there are effectively no normal shared-library boundaries to hook. ", Code "ldd", Text " reports the executable as statically linked. Techniques built around replacing dynamically linked functions with ", Code "LD_PRELOAD", Text " are therefore poor fits."], Heading 2 "proving-that-it-is-native-rust" [Text "Proving that it is native Rust"], Paragraph [Text "Searching for words like ", Code "node_modules", Text ", ", Code "bun", Text ", or ", Code "Node.js", Text " is not enough. A large native application may contain those terms because it understands JavaScript projects, invokes package managers, or ships a web-development tool. The compiler metadata gives a much stronger answer:"], CodeBlock (Just "bash") [Text "readelf -p .comment ", Span "hljs-string" [Text "\"", Span "hljs-variable" [Text "$target"], Text "\""], Text "\nobjdump -s -j .debug_gdb_scripts ", Span "hljs-string" [Text "\"", Span "hljs-variable" [Text "$target"], Text "\""], Text "\n"], Paragraph [Text "The ", Code ".comment", Text " section identifies:"], CodeBlock (Just "text") [Text "rustc version 1.92.0 (ded5c06cf 2025-12-08)\nGCC: (GNU) 9.4.0\nGCC: (Ubuntu 11.4.0-1ubuntu1~22.04.2) 11.4.0\n"], Paragraph [Text "The ", Code ".debug_gdb_scripts", Text " section asks GDB to load Rust pretty-printers. Dependency paths embedded in the read-only data also name Rust crates with exact versions, including ", Code "tokio", Text ", ", Code "reqwest", Text ", ", Code "rustls", Text ", ", Code "ratatui", Text ", ", Code "rusqlite", Text ", ", Code "git2", Text ", ", Code "gix", Text ", ", Code "tonic", Text ", ", Code "prost", Text ", ", Code "rmcp", Text ", and ", Code "agent-client-protocol", Text "."], Paragraph [Text "This is not a thin Rust launcher around a hidden JavaScript payload. The native code section alone is more than 100 MiB. The crate inventory matches the features visible in the product: async orchestration, HTTP streaming, a terminal UI, SQLite search, Git worktrees, protobuf messages, MCP, and ACP."], Paragraph [Text "The binary also contains a ", Code ".gnu_debuglink", Text " entry:"], CodeBlock (Just "text") [Text "xai-grok-pager.debug\n"], Paragraph [Text "That filename is important. It means the release process produced or expected a separate debug-symbol artifact. The symbol file was not installed and I did not find it in the public distribution, but the exact matching file would be far more valuable than guessing function boundaries in an optimized release. GDB, Ghidra, IDA, or Binary Ninja could use it to recover names, types, and source-line associations."], Heading 2 "what-stripped-really-removes" [Text "What stripped really removes"], Paragraph [Text "“Stripped” often gets treated as if it means “opaque.” It does not. Stripping primarily removes the convenient symbol and debug tables. It does not automatically remove every string literal, serialization field, tracing event, panic location, protocol name, error message, or source path that the program needs at runtime."], Paragraph [Text "Rust applications are especially generous when they use structured tracing. A call such as ", Code "tracing::event!", Text " can preserve module and source-file metadata through ", Code "file!()", Text " and ", Code "module_path!()", Text ". Serde-generated code leaks structure names and field names. Clap retains command names, argument descriptions, and possible values. Protobuf and JSON-RPC layers retain method and message identifiers."], Paragraph [Text "A broad ", Code "strings", Text " dump is noisy, so I narrowed it to source-shaped patterns:"], CodeBlock (Just "bash") [Text "strings -a ", Span "hljs-string" [Text "\"", Span "hljs-variable" [Text "$target"], Text "\""], Text " \\\n  | rg -o ", Span "hljs-string" [Text "'crates/codegen/[A-Za-z0-9_./-]+\\.rs'"], Text " \\\n  | ", Span "hljs-built_in" [Text "sort"], Text " -u\n"], Paragraph [Text "The result is not source code, but it is close to an architectural index. This is the key distinction: decompilation tries to reconstruct implementation. Metadata recovery reconstructs responsibility and boundaries. For learning how an agent works, the second one often gets us to the useful questions faster."], Heading 2 "recovering-the-internal-crate-map" [Text "Recovering the internal crate map"], Paragraph [Text "The first-party crate names form a fairly clean system map:"], Table [[[Text "Crate"], [Text "Likely responsibility, supported by module paths"]]] [[[Code "xai-grok-pager"], [Text "Full-screen terminal UI and subagent views"]], [[Code "xai-grok-shell"], [Text "CLI, ACP sessions, orchestration, persistence, permissions"]], [[Code "xai-chat-state"], [Text "Conversation state and construction of model requests"]], [[Code "xai-grok-sampler"], [Text "Streaming inference and retries"]], [[Code "xai-grok-tools"], [Text "Built-in tool definitions and schemas"]], [[Code "xai-tool-runtime"], [Text "Tool execution protocol and progress events"]], [[Code "xai-grok-mcp"], [Text "MCP discovery and dispatch"]], [[Code "xai-grok-hooks"], [Text "Lifecycle hooks around prompts and tools"]], [[Code "xai-grok-sandbox"], [Text "Landlock/Seatbelt execution isolation"]], [[Code "xai-grok-subagent-resolution"], [Text "Child role, persona, model, and capability resolution"]], [[Code "xai-grok-compaction"], [Text "Context-window compression"]], [[Code "xai-grok-memory"], [Text "Cross-session memory"]], [[Code "xai-hunk-tracker"], [Text "File changes, diffs, rewind, and review state"]]], Paragraph [Text "The main shell crate exposes even more specific modules:"], CodeBlock (Just "text") [Text "session/acp_session_impl/prompt_build.rs\nsession/acp_session_impl/run_loop.rs\nsession/acp_session_impl/sampler_turn.rs\nsession/acp_session_impl/tool_calls.rs\nsession/acp_session_impl/tool_dispatch.rs\nsession/acp_session_impl/turn_end.rs\nsession/acp_session_impl/reminders.rs\nsession/acp_session_impl/laziness_classifier.rs\nsession/persistence.rs\nsession/storage/jsonl.rs\nagent/mvp_agent/subagent_coordinator.rs\nagent/subagent.rs\n"], Paragraph [Text "Even without function bodies, those names expose a sequence. A session is set up, its prompt is built, a sampler turn streams model output, tool calls are collected and dispatched, results are folded back into chat state, and the turn is finalized and persisted."], Paragraph [Text "There are also separate goal-related modules: planner, strategist, summarizer, classifier, tracker, verifier, and stop detector. One embedded prompt belongs to a strict JSON classifier that decides whether the main agent is stalled. It looks for narration that claims an action without a matching tool call, or a completion claim unsupported by tool evidence. This is a useful reminder that what feels like one agent in the UI can actually include several narrow model-assisted control passes around the primary conversation."], Heading 2 "reconstructing-the-agent-loop" [Text "Reconstructing the agent loop"], Paragraph [Text "Putting together the crate names, protocol fields, local documentation, and session format produces this high-level loop:"], CodeBlock (Just "text") [Text "                         build model request\n                                  │\n                                  ▼\n┌──────────── request_builder: model-visible context ────────────┐\n│ system prompt                                                  │\n│   ├── selected agent definition                                │\n│   ├── AGENTS.md + applicable project rules                     │\n│   ├── skills, memory, plan state, and reminders                │\n│   └── available local + MCP tool schemas                       │\n│                                                                │\n│ conversation                                                   │\n│   └── prior messages + tool results + current user prompt      │\n└──────────────────────────────┬─────────────────────────────────┘\n                               │ serialized request\n                               ▼\n                       inference backend\n"], Paragraph [Text "The request enters the session run loop. The backend produces a stream rather than one monolithic answer. Text can be rendered immediately, while a tool call creates a local execution detour and then feeds its result into another model pass:"], CodeBlock (Just "text") [Text "                             session/prompt\n                                   │\n                                   ▼\n┌──────────── session run_loop ────────────────────────────────┐\n│ prompt_build → sampler_turn → streaming backend              │\n│                                                              │\n│ text / reasoning                                             │\n│   └──► emit ACP/TUI update + append updates.jsonl            │\n│                                                              │\n│ tool_call                                                    │\n│   └──► tool_dispatch → structured result → chat state        │\n│                                                │             │\n│                         next sampler turn ◄────┘             │\n│                                                              │\n│ final status                                                 │\n│   └──► turn_end → signals + persistence                      │\n│          └──► reminders / compaction check                   │\n└──────────────────────────────────────────────────────────────┘\n"], Paragraph [Text "That detour is a pipeline of gates. A denial stops before execution; approval continues toward the operating-system boundary:"], CodeBlock (Just "text") [Text "                             tool_call(args)\n                                   │\n                                   ▼\n┌──────────── local tool dispatcher ────────────────────────────┐\n│ 1. deserialize and validate arguments                         │\n│        │                                                      │\n│ 2. run matching PreToolUse hooks ───── deny ────┐             │\n│        │ allow / no decision                    │             │\n│ 3. evaluate permission rules ───────── deny ────┤             │\n│        │ allow / user approves                  │             │\n│ 4. enter OS sandbox                             │             │\n│        │                                        │             │\n│        └──► file / shell / Git / MCP / web / subagent         │\n│                    │                            │             │\n│                    └── success or error ────────┤             │\n│                                                 ▼             │\n│                          normalize as structured tool result  │\n└──────────────────────────────┬────────────────────────────────┘\n                               │ structured result\n                               ▼\n                    chat state → next model pass\n"], Paragraph [Text "“Build request context” is doing a lot of work here. It can include the base system prompt, selected agent definition, project instruction files such as ", Code "AGENTS.md", Text ", skill descriptions, memory, MCP tools, file references, prior conversation, plan state, reminders, and the current tool schemas. The ", Code "xai-chat-state", Text " request builder then serializes that state for the selected backend."], Paragraph [Text "The model is not directly executing shell commands. It emits a structured request. The client decides whether the tool exists, whether its arguments deserialize, whether a hook denies it, whether permission policy allows it, and whether the operating-system sandbox permits the underlying action. This separation matters because “the model can use Bash” really means “the harness exposed a Bash-shaped schema and agreed to execute a validated request under several local policy layers.”"], Paragraph [Text "The ordering documented by Grok Build is:"], OrderedList [[Plain [Text "Blocking ", Code "PreToolUse", Text " hooks."]], [Plain [Text "Explicit permission rules, with deny taking precedence."]], [Plain [Text "Built-in fast paths for read-only or recognized-safe operations."]], [Plain [Text "The active prompt policy, such as asking the user or always approving."]], [Plain [Text "The OS sandbox, which remains a separate enforcement boundary."]]], Paragraph [Text "The official enterprise documentation confirms that the Linux sandbox uses Landlock and that network communication uses ", Code "rustls", Text ", not OpenSSL.", FootnoteRef 1 "fnref1", Text " The dependency inventory in the binary independently matches both claims."], Heading 2 "acp-is-the-cleanest-observation-point" [Text "ACP is the cleanest observation point"], Paragraph [Text "Native disassembly is not the only interface. Grok Build implements the Agent Client Protocol, a JSON-RPC protocol designed for editors and other agent clients.", FootnoteRef 2 "fnref2", Text " Its standard input mode can be queried without opening the interactive TUI:"], CodeBlock (Just "bash") [Text "grok agent --no-leader stdio\n"], Paragraph [Text "I sent a single ", Code "initialize", Text " request:"], CodeBlock (Just "json") [Span "hljs-punctuation" [Text "{"], Text "\n  ", Span "hljs-attr" [Text "\"jsonrpc\""], Span "hljs-punctuation" [Text ":"], Text " ", Span "hljs-string" [Text "\"2.0\""], Span "hljs-punctuation" [Text ","], Text "\n  ", Span "hljs-attr" [Text "\"id\""], Span "hljs-punctuation" [Text ":"], Text " ", Span "hljs-number" [Text "1"], Span "hljs-punctuation" [Text ","], Text "\n  ", Span "hljs-attr" [Text "\"method\""], Span "hljs-punctuation" [Text ":"], Text " ", Span "hljs-string" [Text "\"initialize\""], Span "hljs-punctuation" [Text ","], Text "\n  ", Span "hljs-attr" [Text "\"params\""], Span "hljs-punctuation" [Text ":"], Text " ", Span "hljs-punctuation" [Text "{"], Text "\n    ", Span "hljs-attr" [Text "\"protocolVersion\""], Span "hljs-punctuation" [Text ":"], Text " ", Span "hljs-number" [Text "1"], Span "hljs-punctuation" [Text ","], Text "\n    ", Span "hljs-attr" [Text "\"clientCapabilities\""], Span "hljs-punctuation" [Text ":"], Text " ", Span "hljs-punctuation" [Text "{"], Text "\n      ", Span "hljs-attr" [Text "\"fs\""], Span "hljs-punctuation" [Text ":"], Text " ", Span "hljs-punctuation" [Text "{"], Text "\n        ", Span "hljs-attr" [Text "\"readTextFile\""], Span "hljs-punctuation" [Text ":"], Text " ", Span "hljs-literal" [Span "hljs-keyword" [Text "true"]], Span "hljs-punctuation" [Text ","], Text "\n        ", Span "hljs-attr" [Text "\"writeTextFile\""], Span "hljs-punctuation" [Text ":"], Text " ", Span "hljs-literal" [Span "hljs-keyword" [Text "true"]], Text "\n      ", Span "hljs-punctuation" [Text "}"], Span "hljs-punctuation" [Text ","], Text "\n      ", Span "hljs-attr" [Text "\"terminal\""], Span "hljs-punctuation" [Text ":"], Text " ", Span "hljs-literal" [Span "hljs-keyword" [Text "true"]], Text "\n    ", Span "hljs-punctuation" [Text "}"], Span "hljs-punctuation" [Text ","], Text "\n    ", Span "hljs-attr" [Text "\"clientInfo\""], Span "hljs-punctuation" [Text ":"], Text " ", Span "hljs-punctuation" [Text "{"], Text "\n      ", Span "hljs-attr" [Text "\"name\""], Span "hljs-punctuation" [Text ":"], Text " ", Span "hljs-string" [Text "\"local-analysis\""], Span "hljs-punctuation" [Text ","], Text "\n      ", Span "hljs-attr" [Text "\"version\""], Span "hljs-punctuation" [Text ":"], Text " ", Span "hljs-string" [Text "\"0\""], Text "\n    ", Span "hljs-punctuation" [Text "}"], Text "\n  ", Span "hljs-punctuation" [Text "}"], Text "\n", Span "hljs-punctuation" [Text "}"], Text "\n"], Paragraph [Text "The response advertised session loading, embedded context, MCP over HTTP and SSE, filesystem notifications, blocking pre-tool hooks, model state, and built-in commands including ", Code "compact", Text ", ", Code "context", Text ", ", Code "session-info", Text ", and ", Code "goal", Text ". No inference request was needed to learn this."], Paragraph [Text "ACP gives us a stable seam between presentation and orchestration:"], CodeBlock (Just "text") [Text "ACP client ⇄ JSON-RPC over stdin/stdout ⇄ grok agent stdio\n                                              │\n                                              ▼\n┌──────────── ACP request router + session manager ─────────────┐\n│ initialize                                                    │\n│   └──► return protocol, agent, auth, and MCP capabilities     │\n│                                                               │\n│ session/new or session/load                                   │\n│   └──► create or restore an active AcpSession                 │\n│                                                               │\n│ session/prompt                                                │\n│   └──► active session run_loop                                │\n│             ├──► inference backend                            │\n│             ├──► built-in tools + configured MCP servers      │\n│             └──► session state                                │\n│                      │                                        │\n│                      ├──► persist updates.jsonl               │\n│                      └──► emit session/update to client       │\n│                                                               │\n│ tool approval                                                 │\n│   └──► session/request_permission ⇄ client response           │\n└───────────────────────────────────────────────────────────────┘\n"], Paragraph [Text "The client sends ", Code "initialize", Text ", ", Code "session/new", Text ", ", Code "session/load", Text ", and ", Code "session/prompt", Text " requests. Grok returns normal JSON-RPC responses and streams ", Code "session/update", Text " notifications containing message chunks, thought chunks, plans, and tool state. When a tool requires approval, Grok sends the client a ", Code "session/request_permission", Text " request and waits for its response. The client sees these protocol state transitions, not Rust function calls."], Paragraph [Text "A transparent ACP proxy is therefore one of the best research tools for this application. It can log method names, session updates, reasoning chunks exposed by the protocol, permission requests, tool-call status, plans, and final messages. It will not reveal every internal Rust call, but it reveals the state transitions that actually matter to an editor or orchestration client."], Paragraph [Text "The product itself officially supports interactive, headless, and ACP modes.", FootnoteRef 3 "fnref3", Text " That makes ACP observation less brittle than hooking private functions whose addresses may change in every release."], Heading 2 "how-subagents-are-represented" [Text "How subagents are represented"], Paragraph [Text "Subagents are not threads sharing one prompt buffer. They are child sessions with their own conversation context. The parent model requests one through a ", Code "spawn_subagent", Text " tool, passing a task description and an agent type. Resolution then combines the selected role with optional model overrides, persona instructions, capability restrictions, and isolation settings."], Paragraph [Text "The built-in roles are:"], Table [[[Text "Type"], [Text "Default purpose"]]] [[[Code "general-purpose"], [Text "Full-capability implementation and general work"]], [[Code "explore"], [Text "Read/search/execute investigation without file editing"]], [[Code "plan"], [Text "Codebase exploration followed by an implementation plan"]]], Paragraph [Text "Capabilities can be restricted independently to read-only, read-write, execute, or all. Isolation is either the shared working directory or a separate Git worktree. A background child returns immediately with an ID; the parent later retrieves its progress or result. A blocking child holds the parent call until completion."], CodeBlock (Just "text") [Text "┌───────────────────────────────────────────────────────────────────────┐\n│ PARENT SESSION                                                        │\n│                                                                       │\n│ model decides that a bounded task can be delegated                    │\n└───────────────────────────────────┬───────────────────────────────────┘\n                                    │\n                                    │ spawn_subagent {\n                                    │   prompt, description, type,\n                                    │   background, capability, isolation\n                                    │ }\n                                    ▼\n                      ┌───────────────────────────┐\n                      │ subagent resolution       │\n                      │                           │\n                      │  1. choose agent role     │\n                      │  2. apply persona         │\n                      │  3. resolve model         │\n                      │  4. restrict tools        │\n                      │  5. choose cwd/worktree   │\n                      └─────────────┬─────────────┘\n                                    │\n                                    ▼\n┌───────────────────────────────────────────────────────────────────────┐\n│ CHILD SESSION                                                         │\n│                                                                       │\n│ separate context window     separate transcript     normal agent loop │\n│                                                                       │\n│              workspace choice:                                        │\n│              ┌────────────────────┐     ┌─────────────────────────┐   │\n│              │ same working tree  │ OR  │ isolated Git worktree   │   │\n│              └────────────────────┘     └─────────────────────────┘   │\n└───────────────────────────────────┬───────────────────────────────────┘\n                                    │\n                      progress ─────┼───── completion\n                                    │\n                                    ▼\n                      ┌───────────────────────────┐\n                      │ compact result / summary  │\n                      └─────────────┬─────────────┘\n                                    │\n                                    ▼\n┌───────────────────────────────────────────────────────────────────────┐\n│ PARENT CONTINUES                                                      │\n│ full child transcript stays separate; only the result enters context  │\n└───────────────────────────────────────────────────────────────────────┘\n\nDepth limit: parent → child. A child cannot create a grandchild.\n"], Paragraph [Text "Only the child pays for its full working transcript in its context window. A background child returns an ID immediately and the parent retrieves its progress or completion later with ", Code "get_command_or_subagent_output", Text "."], Paragraph [Text "The nesting depth is intentionally one: only the top-level session can spawn subagents. This keeps the graph flat and prevents recursive fan-out. A resumed child can inherit a completed child transcript, tool state, model, and working directory, but its current system prompt and tools are rendered again from the active agent definition. The source child must be complete, belong to the current parent session, and use the same agent type."], Paragraph [Text "This architecture explains why subagents save context in the parent. The parent does not need every search result and failed command in its own history. It receives a compressed result while the complete child transcript remains separately inspectable."], Heading 2 "persistence-makes-the-runtime-inspectable" [Text "Persistence makes the runtime inspectable"], Paragraph [Text "Every mode writes the same general session model under ", Code "~/.grok/sessions/", Text ". A session directory contains files such as:"], CodeBlock (Just "text") [Text "                         append(session event)\n                                  │\n                                  ▼\n┌──────────── session directory (source of truth) ──────────────┐\n│ ├── updates.jsonl → ACP event stream → restore / TUI replay   │\n│ ├── chat_history.jsonl → raw messages for model requests      │\n│ ├── summary.json → title, model, timestamps, message counts   │\n│ ├── signals.json → token, turn, and tool counters             │\n│ ├── plan.json → task state                                    │\n│ ├── rewind_points.jsonl → file restoration                    │\n│ └── subagents/ → child metadata                               │\n│                                                               │\n│ compaction_checkpoints/ → transformed conversation snapshots  │\n└───────────────────────────────────────────────────────────────┘\n\nsearch: titles + prompts → SQLite FTS index\n"], Paragraph [Code "updates.jsonl", Text " is the ACP-style event stream used for restoration. ", Code "chat_history.jsonl", Text " contains the raw conversation messages used by the model-facing state. Smaller JSON files track plans, usage signals, summaries, and rewind state. Session search additionally maintains a SQLite FTS index."], Paragraph [Text "This is more useful than it first appears. To understand an agent turn, we can correlate:"], BulletList [[Plain [Text "the user message in ", Code "chat_history.jsonl", Text ";"]], [Plain [Text "emitted reasoning and tool events in ", Code "updates.jsonl", Text ";"]], [Plain [Text "the tool result attached to the next model request;"]], [Plain [Text "turn and token counters in ", Code "signals.json", Text ";"]], [Plain [Text "child metadata under ", Code "subagents/", Text ";"]], [Plain [Text "debug logs enabled with ", Code "--debug-file", Text "."]]], Paragraph [Text "That creates a behavioral trace without touching the ELF. It also separates two commonly confused histories: what the user interface rendered and what the model actually received after normalization, pruning, repair, or compaction."], Paragraph [Text "Embedded log messages show that the chat-state layer repairs duplicate results and dangling tool calls after crashes. Compaction has its own checkpoints and transcript transformation code. This means a resumed session is not simply replaying a text file; it is reconstructing a consistent state machine from persisted events."], Heading 2 "modification-without-patching-machine-code" [Text "Modification without patching machine code"], Paragraph [Text "If the goal is to learn how the agent behaves, patching instructions in ", Code ".text", Text " should be near the bottom of the list. Grok Build already exposes several modification layers with much better stability."], CodeBlock (Just "text") [Text "least invasive / most update-resistant\n                    │\n                    ▼\n1. config + rules       change prompts, agents, tools, and models\n                    │\n2. lifecycle hooks      observe or deny tool execution\n                    │\n3. ACP proxy            observe requests, updates, and permissions\n                    │\n4. local model endpoint  capture the exact model-facing request\n                    │\n5. native decompiler    recover private control flow\n                    │\n6. binary patch         modify strings or machine instructions\n                    │\n                    ▼\nmost invasive / tied to one release build\n"], Heading 3 "replace-or-extend-the-prompt" [Text "Replace or extend the prompt"], Paragraph [Text "The CLI supports both:"], CodeBlock (Just "bash") [Text "grok --rules ", Span "hljs-string" [Text "\"Additional session-specific rules\""], Text "\ngrok --system-prompt-override ", Span "hljs-string" [Text "\"A complete replacement system prompt\""], Text "\n"], Paragraph [Text "Project ", Code "AGENTS.md", Text " files, custom agent definitions under ", Code ".grok/agents/", Text ", personas, and role prompt files offer more durable variants. These are ideal for testing whether a behavior comes from prompting or from harness logic."], Heading 3 "interpose-at-the-lifecycle-boundary" [Text "Interpose at the lifecycle boundary"], Paragraph [Text "Hooks can observe session start, user prompts, tool requests, results, permission denial, compaction, subagent start/stop, and turn completion. ", Code "PreToolUse", Text " hooks can deny an operation. Passive hooks can log a structured event stream."], Paragraph [Text "This is the right layer for experiments such as:"], BulletList [[Plain [Text "recording every tool and its arguments;"]], [Plain [Text "blocking a command family;"]], [Plain [Text "measuring time between model output and tool completion;"]], [Plain [Text "comparing main-agent and subagent tool patterns;"]], [Plain [Text "injecting controlled environment state at session start."]]], Heading 3 "wrap-acp" [Text "Wrap ACP"], Paragraph [Text "A small proxy can launch ", Code "grok agent stdio", Text ", forward newline-delimited JSON in both directions, and write a timestamped copy. Because it works at the documented protocol boundary, it should survive internal Rust refactors better than an address-based hook."], Heading 3 "capture-the-model-facing-request-locally" [Text "Capture the model-facing request locally"], Paragraph [Text "Grok supports custom OpenAI-compatible model endpoints. In an isolated lab configuration, a local endpoint can capture the request body and return a canned response. The important safety rules are to use a temporary ", Code "GROK_HOME", Text ", a dummy API key, and an empty test workspace so no real credentials, project instructions, memory, or private source code enter the capture."], Paragraph [Text "A minimal model definition looks conceptually like this:"], CodeBlock (Just "toml") [Span "hljs-section" [Text "[models]"], Text "\n", Span "hljs-attr" [Text "default"], Text " = ", Span "hljs-string" [Text "\"capture\""], Text "\n\n", Span "hljs-section" [Text "[model.capture]"], Text "\n", Span "hljs-attr" [Text "model"], Text " = ", Span "hljs-string" [Text "\"capture\""], Text "\n", Span "hljs-attr" [Text "base_url"], Text " = ", Span "hljs-string" [Text "\"http://127.0.0.1:8080/v1\""], Text "\n", Span "hljs-attr" [Text "api_key"], Text " = ", Span "hljs-string" [Text "\"dummy\""], Text "\n", Span "hljs-attr" [Text "context_window"], Text " = ", Span "hljs-number" [Text "128000"], Text "\n"], Paragraph [Text "This experiment can reveal the exact rendered system prompt, message ordering, tool schemas, reminders, and provider API dialect. For studying an agent harness, that is usually more informative than pseudocode reconstructed from optimized assembly."], Heading 2 "when-native-decompilation-is-still-useful" [Text "When native decompilation is still useful"], Paragraph [Text "There are questions the public boundaries cannot answer. Native analysis becomes useful when we need the precise precedence of undocumented flags, the implementation of a parser, a hidden state transition, the source of a crash, or the location of an internal constant."], Paragraph [Text "The practical route would be:"], OrderedList [[Plain [Text "Preserve the original hash and work on a copy."]], [Plain [Text "Import the ELF as x86-64 little-endian in Ghidra, IDA, or Binary Ninja."]], [Plain [Text "Mark the image as PIE and use the ELF program headers rather than guessing a base address."]], [Plain [Text "Apply Rust demangling and known library signatures."]], [Plain [Text "Use embedded source paths and tracing strings to label functions by responsibility."]], [Plain [Text "Locate cross-references to distinctive errors or protocol method strings."]], [Plain [Text "Compare behavior across two releases to separate stable subsystems from compiler noise."]], [Plain [Text "Load ", Code "xai-grok-pager.debug", Text " if an exact matching symbol artifact becomes available."]]], Paragraph [Text "The best initial targets are not ", Code "main", Text ". Optimized Rust startup mostly leads into runtime and argument-parsing machinery. Better anchors are distinctive strings associated with:"], CodeBlock (Just "text") [Text "session/prompt\nsession/request_permission\nspawn_subagent\ntool.call\ntool.cancel\ncompact_conversation\nactive_sessions.json\nupdates.jsonl\n"], Paragraph [Text "From each string, follow read-only-data references into code, then expand the call graph. Serde and protobuf-generated functions can be large and repetitive, so they should be labeled early to avoid mistaking serialization machinery for business logic."], Paragraph [Text "Binary patching is possible, but the useful cases are narrow. A same-length string replacement in ", Code ".rodata", Text " is manageable. Changing string length requires relocating data or rewriting references. Control-flow patches must account for optimized code, RIP-relative addressing, unwinding metadata, and ASLR. The internal updater will replace the modified artifact on the next update."], Paragraph [Text "Because the binary is statically linked, ", Code "LD_PRELOAD", Text " will not give normal interposition points. Because HTTPS is implemented with ", Code "rustls", Text ", OpenSSL function hooks will not expose plaintext. Explicit protocol proxies, custom endpoints, ACP wrappers, hooks, ", Code "ptrace", Text ", or uprobes are more appropriate depending on the question."], Heading 2 "a-practical-research-workflow" [Text "A practical research workflow"], Paragraph [Text "If I continued this project, I would avoid starting with a full decompile. I would build the evidence in layers:"], Heading 3 "phase-one-inventory" [Text "Phase one: inventory"], CodeBlock (Just "bash") [Text "file -L ", Span "hljs-string" [Text "\"", Span "hljs-variable" [Text "$target"], Text "\""], Text "\nreadelf -hW ", Span "hljs-string" [Text "\"", Span "hljs-variable" [Text "$target"], Text "\""], Text "\nreadelf -SW ", Span "hljs-string" [Text "\"", Span "hljs-variable" [Text "$target"], Text "\""], Text "\nreadelf -p .comment ", Span "hljs-string" [Text "\"", Span "hljs-variable" [Text "$target"], Text "\""], Text "\nreadelf -x .gnu_debuglink ", Span "hljs-string" [Text "\"", Span "hljs-variable" [Text "$target"], Text "\""], Text "\nstrings -a ", Span "hljs-string" [Text "\"", Span "hljs-variable" [Text "$target"], Text "\""], Text " | rg ", Span "hljs-string" [Text "'crates/codegen|session/prompt|spawn_subagent'"], Text "\n"], Paragraph [Text "Record the version, build ID, compiler, hash, sections, source paths, dependencies, endpoints, environment variables, and protocol identifiers."], Heading 3 "phase-two-observe-public-behavior" [Text "Phase two: observe public behavior"], Paragraph [Text "Run the ACP initialization handshake, enumerate CLI help recursively, inspect discovered configuration with ", Code "grok inspect", Text ", and read the locally installed user guide. None of these steps requires a paid model turn."], Heading 3 "phase-three-trace-one-controlled-session" [Text "Phase three: trace one controlled session"], Paragraph [Text "Use an empty repository and a harmless prompt. Save ACP traffic, debug logs, session JSONL, hooks, and filesystem changes. Correlate events by session ID and tool-call ID."], Heading 3 "phase-four-isolate-one-question" [Text "Phase four: isolate one question"], Paragraph [Text "Examples:"], BulletList [[Plain [Text "What exactly is sent to a subagent?"]], [Plain [Text "When is a stalled turn automatically continued?"]], [Plain [Text "How does permission precedence handle conflicting rules?"]], [Plain [Text "Which content survives compaction?"]], [Plain [Text "Does a resumed child inherit the old prompt or re-render the current one?"]]], Paragraph [Text "Use the least invasive boundary that answers the question. Only move to native decompilation if ACP, hooks, logs, persistence, and a controlled endpoint cannot resolve it."], Heading 3 "phase-five-patch-a-disposable-copy" [Text "Phase five: patch a disposable copy"], Paragraph [Text "If a machine-code modification is genuinely necessary, redirect a separate launcher to the copy and disable auto-update for the experiment. Never edit the symlink target without a rollback path. Verify the copy’s hash before and after every change and document file offsets separately from runtime virtual addresses."], Heading 2 "what-this-tells-us-about-coding-agents" [Text "What this tells us about coding agents"], Paragraph [Text "The most interesting result is not that Grok Build is written in Rust. It is how much of the “agent” lives outside the model."], Paragraph [Text "The model proposes text and structured actions, but the harness constructs its context, defines the available actions, validates arguments, asks for permission, executes tools, stores results, repairs history, compacts old context, coordinates child sessions, detects stalls, manages worktrees, and decides when a turn has actually ended. The visible personality may come from a prompt and a model, but reliability comes from a state machine surrounding them."], Paragraph [Text "That state machine is also the most practical place to learn. ACP shows the session boundary. Hooks show policy decisions. JSONL shows history. A local model endpoint shows the rendered request. The ELF fills in the internal subsystem names and helps answer the remaining implementation questions."], Paragraph [Text "So the original JavaScript hypothesis was wrong, but the conclusion is better: we do not need source maps to understand an agent harness. We need to identify its boundaries, choose the right observation point, and separate evidence from inference. Native code makes the last ten percent harder. It does not hide the shape of the system."], Paragraph [Text "At the time of this investigation, xAI describes Grok Build as an early-beta coding agent supporting TUI, headless automation, ACP, skills, plugins, hooks, MCP, and subagents.", FootnoteRef 4 "fnref4", Text " The public xAI GitHub organization did not list the CLI source itself, so the local artifact and its documented protocols remain the primary material for this kind of study.", FootnoteRef 5 "fnref5"], Footnotes [Footnote 1 ["fnref1"] [Paragraph [Text "xAI, ", Link "https://docs.x.ai/build/enterprise" Nothing [Text "“Enterprise Deployments”"], Text ", including network, configuration, authentication, sandbox, permission, and TLS details."]], Footnote 2 ["fnref2"] [Paragraph [Link "https://agentclientprotocol.com" Nothing [Text "Agent Client Protocol"], Text ", the JSON-RPC protocol used by ", Code "grok agent stdio", Text "."]], Footnote 3 ["fnref3"] [Paragraph [Text "xAI, ", Link "https://docs.x.ai/build/overview" Nothing [Text "“Grok Build”"], Text ", official product and CLI overview."]], Footnote 4 ["fnref4"] [Paragraph [Text "xAI, ", Link "https://x.ai/news/grok-build-cli" Nothing [Text "“Introducing Grok Build”"], Text ", May 25, 2026."]], Footnote 5 ["fnref5"] [Paragraph [Link "https://github.com/orgs/xai-org/repositories" Nothing [Text "xAI’s public GitHub repositories"], Text ", checked during the investigation on July 10, 2026."]]]]
    , postToc = [TocEntry { tocId = "table-of-contents", tocLabel = "Table of Contents", tocLevel = 2 }, TocEntry { tocId = "start-with-the-artifact-not-the-interface", tocLabel = "Start with the artifact, not the interface", tocLevel = 2 }, TocEntry { tocId = "proving-that-it-is-native-rust", tocLabel = "Proving that it is native Rust", tocLevel = 2 }, TocEntry { tocId = "what-stripped-really-removes", tocLabel = "What stripped really removes", tocLevel = 2 }, TocEntry { tocId = "recovering-the-internal-crate-map", tocLabel = "Recovering the internal crate map", tocLevel = 2 }, TocEntry { tocId = "reconstructing-the-agent-loop", tocLabel = "Reconstructing the agent loop", tocLevel = 2 }, TocEntry { tocId = "acp-is-the-cleanest-observation-point", tocLabel = "ACP is the cleanest observation point", tocLevel = 2 }, TocEntry { tocId = "how-subagents-are-represented", tocLabel = "How subagents are represented", tocLevel = 2 }, TocEntry { tocId = "persistence-makes-the-runtime-inspectable", tocLabel = "Persistence makes the runtime inspectable", tocLevel = 2 }, TocEntry { tocId = "modification-without-patching-machine-code", tocLabel = "Modification without patching machine code", tocLevel = 2 }, TocEntry { tocId = "replace-or-extend-the-prompt", tocLabel = "Replace or extend the prompt", tocLevel = 3 }, TocEntry { tocId = "interpose-at-the-lifecycle-boundary", tocLabel = "Interpose at the lifecycle boundary", tocLevel = 3 }, TocEntry { tocId = "wrap-acp", tocLabel = "Wrap ACP", tocLevel = 3 }, TocEntry { tocId = "capture-the-model-facing-request-locally", tocLabel = "Capture the model-facing request locally", tocLevel = 3 }, TocEntry { tocId = "when-native-decompilation-is-still-useful", tocLabel = "When native decompilation is still useful", tocLevel = 2 }, TocEntry { tocId = "a-practical-research-workflow", tocLabel = "A practical research workflow", tocLevel = 2 }, TocEntry { tocId = "phase-one-inventory", tocLabel = "Phase one: inventory", tocLevel = 3 }, TocEntry { tocId = "phase-two-observe-public-behavior", tocLabel = "Phase two: observe public behavior", tocLevel = 3 }, TocEntry { tocId = "phase-three-trace-one-controlled-session", tocLabel = "Phase three: trace one controlled session", tocLevel = 3 }, TocEntry { tocId = "phase-four-isolate-one-question", tocLabel = "Phase four: isolate one question", tocLevel = 3 }, TocEntry { tocId = "phase-five-patch-a-disposable-copy", tocLabel = "Phase five: patch a disposable copy", tocLevel = 3 }, TocEntry { tocId = "what-this-tells-us-about-coding-agents", tocLabel = "What this tells us about coding agents", tocLevel = 2 }]
